import {defaultHair,validateHair} from './pose-hair.js';
// POSE1A: original authored rig and poses. No downloaded models or inference.
export const POSE_KEY='unruly-pose-library-v1', MAX_RECORDS=64, MAX_PLACEMENTS=32, MAX_BYTES=524288;
const I=[0,0,0,1], rad=Math.PI/180;
export const add=(a,b)=>a.map((v,i)=>v+b[i]), sub=(a,b)=>a.map((v,i)=>v-b[i]), mul=(a,s)=>a.map(v=>v*s), dot=(a,b)=>a.reduce((n,v,i)=>n+v*b[i],0), norm=a=>Math.hypot(...a);
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]], unit=a=>norm(a)>1e-10?mul(a,1/norm(a)):[1,0,0];
export function qm(a,b){const v=add(add(mul(b.slice(0,3),a[3]),mul(a.slice(0,3),b[3])),cross(a,b));return [...v,a[3]*b[3]-dot(a.slice(0,3),b.slice(0,3))];}
export const inverse=q=>[-q[0],-q[1],-q[2],q[3]];
export function rotate(q,v){return qm(qm(q,[...v,0]),inverse(q)).slice(0,3);}
export function euler(x=0,y=0,z=0){const a=x*rad/2,b=y*rad/2,c=z*rad/2;return qm(qm([0,0,Math.sin(c),Math.cos(c)],[0,Math.sin(b),0,Math.cos(b)]),[Math.sin(a),0,0,Math.cos(a)]);}
export function toEuler(q){const [x,y,z,w]=q;return [Math.atan2(2*(w*x+y*z),1-2*(x*x+y*y)),Math.asin(Math.max(-1,Math.min(1,2*(w*y-z*x)))),Math.atan2(2*(w*z+x*y),1-2*(y*y+z*z))].map(v=>v/rad);}
function fromTo(a,b){a=unit(a);b=unit(b);const d=dot(a,b);if(d<-.999999){const axis=unit(cross(a,Math.abs(a[0])<.8?[1,0,0]:[0,1,0]));return [...axis,0];}const q=[...cross(a,b),1+d];return mul(q,1/norm(q));}
export const profiles={adult:{torso:1.25,shoulders:.75,hips:.48,upperArm:.82,forearm:.76,thigh:1.1,shin:1.05,neck:.25,head:.34},child:{torso:.95,shoulders:.55,hips:.4,upperArm:.62,forearm:.58,thigh:.8,shin:.78,neck:.18,head:.42},chibi:{torso:.7,shoulders:.48,hips:.38,upperArm:.45,forearm:.42,thigh:.52,shin:.5,neck:.15,head:.65}};
export const profileLabels={torso:'Torso length',shoulders:'Shoulder half-width',hips:'Hip half-width',upperArm:'Upper arm',forearm:'Forearm',thigh:'Thigh',shin:'Shin',neck:'Neck',head:'Head radius'};
export function rig(p){return [
{id:'pelvis',parent:null,v:[0,0,0]}, {id:'chest',parent:'pelvis',v:[0,p.torso,0]}, {id:'neck',parent:'chest',v:[0,p.neck,0]}, {id:'head',parent:'neck',v:[0,p.head,0]},
...['left','right'].flatMap((s,i)=>{const sign=i?-1:1;return [{id:s+'Shoulder',parent:'chest',v:[sign*p.shoulders,0,0]},{id:s+'Elbow',parent:s+'Shoulder',v:[sign*p.upperArm,0,0]},{id:s+'Wrist',parent:s+'Elbow',v:[sign*p.forearm,0,0]},{id:s+'Hip',parent:'pelvis',v:[sign*p.hips,0,0]},{id:s+'Knee',parent:s+'Hip',v:[0,-p.thigh,0]},{id:s+'Ankle',parent:s+'Knee',v:[0,-p.shin,0]},{id:s+'Toe',parent:s+'Ankle',v:[0,-.22,.3]}];})];}
export const jointIds=rig(profiles.adult).map(j=>j.id), endpoints=['leftWrist','rightWrist','leftAnkle','rightAnkle'];
export function neutral(){return {version:1,family:'human',dimensions:3,hair:{...defaultHair},profile:{...profiles.adult},rotations:Object.fromEntries(jointIds.map(id=>[id,[...I]])),pins:{},camera:{focus:'body',yaw:0,pitch:0,zoom:1,perspective:0,panX:0,panY:0},prop:{kind:'none',hand:'rightWrist',length:1.7,angle:0},placement:{x:0,y:0,scale:70,angle:0,opacity:.55,visible:true}};}
export function fk(s){const out={};for(const j of rig(s.profile)){const parent=out[j.parent],q=parent?qm(parent.q,s.rotations[j.id]):s.rotations[j.id];out[j.id]={id:j.id,parent:j.parent,q,p:parent?add(parent.p,rotate(q,j.v)):[0,0,0],rest:j.v};}return out;}
export function cameraQuaternion(c){return euler(c.pitch,c.yaw,0);}
export function project(point,c,width,height){const v=rotate(inverse(cameraQuaternion(c)),sub(point,c.target||[0,-.2,0])),factor=1+c.perspective*(12/(12-v[2])-1),scale=height/6*c.zoom;return {x:width/2+c.panX+v[0]*scale*factor,y:height/2+c.panY-v[1]*scale*factor,z:v[2],factor};}
export function viewCamera(state){return {...state.camera,target:state.camera.focus==='head'?fk(state).head.p:[0,-.2,0]};}
export function unproject(x,y,depth,c,width,height){const scale=height/6*c.zoom,factor=1+c.perspective*(12/(12-depth)-1);return add(rotate(cameraQuaternion(c),[(x-width/2-c.panX)/(scale*factor),-(y-height/2-c.panY)/(scale*factor),depth]),c.target||[0,-.2,0]);}
export function aimJoint(state,id,target){if(id==='pelvis')throw Error('Rotate pelvis with the joint controls');const s=structuredClone(state),f=fk(s),j=f[id],par=f[j.parent],local=rotate(inverse(par.q),sub(target,par.p));if(norm(local)<1e-6)throw Error('Joint target is too close to its parent');s.rotations[id]=fromTo(j.rest,local);return s;}
export function solveEndpoint(state,id,target){if(!endpoints.includes(id))throw Error('Only hands and feet can be pinned');let s=structuredClone(state),f=fk(s);const tip=f[id],mid=f[tip.parent],base=f[mid.parent],a=norm(mid.rest),b=norm(tip.rest),delta=sub(target,base.p),d=norm(delta);if(d>a+b+1e-6||d<Math.abs(a-b)+1e-6)throw Error('Pinned target is unreachable; unpin or move the target');const axis=unit(delta),x=(a*a-b*b+d*d)/(2*d),h=Math.sqrt(Math.max(0,a*a-x*x));let pole=sub(sub(mid.p,base.p),mul(axis,dot(sub(mid.p,base.p),axis)));if(norm(pole)<1e-6)pole=cross(axis,Math.abs(axis[2])<.9?[0,0,1]:[0,1,0]);const knee=add(base.p,add(mul(axis,x),mul(unit(pole),h)));s=aimJoint(s,mid.id,knee);s=aimJoint(s,id,target);return s;}
export function enforcePins(state){let s=structuredClone(state);for(const [id,target] of Object.entries(s.pins))s=solveEndpoint(s,id,target);for(const [id,target] of Object.entries(s.pins))if(norm(sub(fk(s)[id].p,target))>1e-5)throw Error('Pins conflict; unpin an endpoint');return s;}
export function mirror(state){const s=structuredClone(state),swap=id=>id.startsWith('left')?id.replace('left','right'):id.startsWith('right')?id.replace('right','left'):id;s.rotations=Object.fromEntries(Object.entries(state.rotations).map(([id,q])=>[swap(id),[q[0],-q[1],-q[2],q[3]]]));s.pins=Object.fromEntries(Object.entries(state.pins).map(([id,p])=>[swap(id),[-p[0],p[1],p[2]]]));s.prop.hand=swap(s.prop.hand);s.prop.angle=-s.prop.angle;return s;}
const finite=(v,lo,hi)=>typeof v==='number'&&Number.isFinite(v)&&v>=lo&&v<=hi;
function vector(v,n,lo,hi){return Array.isArray(v)&&v.length===n&&v.every(x=>finite(x,lo,hi));}
export function validateState(input){const s=structuredClone(input);if(!s||s.version!==1||s.family!=='human'||s.dimensions!==3)throw Error('Invalid or incompatible pose format');s.hair=validateHair(s.hair);if(s.camera&&s.camera.focus===undefined)s.camera.focus='body';if(!['body','head'].includes(s.camera?.focus))throw Error('Invalid camera focus');for(const key of Object.keys(profiles.adult))if(!finite(s.profile?.[key],.1,2.5))throw Error('Invalid proportions');if(Object.keys(s.rotations||{}).length!==jointIds.length)throw Error('Invalid joint set');for(const id of jointIds)if(!vector(s.rotations[id],4,-1,1)||Math.abs(norm(s.rotations[id])-1)>1e-5)throw Error('Invalid joint rotation');if(!s.pins||Object.keys(s.pins).length>4)throw Error('Invalid pins');for(const [id,p] of Object.entries(s.pins))if(!endpoints.includes(id)||!vector(p,3,-12,12))throw Error('Invalid pin target');const c=s.camera;if(!c||!finite(c.yaw,-360,360)||!finite(c.pitch,-360,360)||!finite(c.zoom,.25,3)||!finite(c.perspective,0,1)||!finite(c.panX,-1000,1000)||!finite(c.panY,-1000,1000))throw Error('Invalid camera');const p=s.prop;if(!p||!['none','object','sword','hammer','box'].includes(p.kind)||!['leftWrist','rightWrist'].includes(p.hand)||!finite(p.length,.2,3)||!finite(p.angle,-180,180))throw Error('Invalid prop');const t=s.placement;if(!t||!finite(t.x,-1e7,1e7)||!finite(t.y,-1e7,1e7)||!finite(t.scale,5,1000)||!finite(t.angle,-180,180)||!finite(t.opacity,.1,1)||typeof t.visible!=='boolean')throw Error('Invalid reference placement');if(Object.values(fk(s)).some(j=>j.p.some(v=>!finite(v,-11,11))))throw Error('Rig exceeds safe bounds');for(const [id,target]of Object.entries(s.pins))if(norm(sub(fk(s)[id].p,target))>1e-4)throw Error('Pin does not match pose');return s;}
export function blankLibrary(){return {version:1,records:[],placements:[]};}
export function validateLibrary(input){if(!input||JSON.stringify(input).length>MAX_BYTES||input.version!==1||!Array.isArray(input.records)||input.records.length>MAX_RECORDS||!Array.isArray(input.placements)||input.placements.length>MAX_PLACEMENTS)throw Error('Invalid or oversized pose library');const ids=new Set(),boards=new Set();for(const r of input.records){if(!r||typeof r.id!=='string'||r.id.length>100||!r.id||ids.has(r.id)||typeof r.name!=='string'||!r.name.trim()||r.name.length>80||!['pose','proportions','combined','hair'].includes(r.kind))throw Error('Invalid saved preset');ids.add(r.id);validateState(r.state);}for(const r of input.placements){if(!r||typeof r.board!=='string'||!r.board||r.board.length>100||boards.has(r.board))throw Error('Invalid board reference');boards.add(r.board);validateState(r.state);}const out=structuredClone(input);out.records=out.records.map(r=>({...r,state:validateState(r.state)}));out.placements=out.placements.map(r=>({...r,state:validateState(r.state)}));if(JSON.stringify(out).length>MAX_BYTES)throw Error('Normalized library exceeds safe bounds');return out;}
export function applyRecord(state,record){const s=validateState(state),r=validateState(record.state);if(record.kind==='combined'){r.placement={...s.placement};return r;}if(record.kind==='pose'){s.rotations=r.rotations;s.prop=r.prop;s.pins={};}else if(record.kind==='proportions'){s.profile=r.profile;s.hair=r.hair;s.pins={};}else if(record.kind==='hair'){s.hair=r.hair;}else throw Error('Invalid preset kind');return validateState(s);}
export function saveRecord(library,state,{id,name,kind,update=false}){const l=validateLibrary(library),s=validateState(state),index=l.records.findIndex(r=>r.id===id);if(update&&index<0)throw Error('Select a saved preset to update');if(!update&&index>=0)throw Error('Preset already exists');const record={id,name:name.trim(),kind,state:s};if(update)l.records[index]=record;else l.records.push(record);return validateLibrary(l);}
export function mergeLibrary(library,incoming,newId){const l=validateLibrary(library),other=validateLibrary(incoming);l.records.push(...other.records.map(r=>({...r,id:newId()})));l.placements.push(...other.placements.filter(r=>!l.placements.some(p=>p.board===r.board)));return validateLibrary(l);}
