export const starters=starts.map(([id,name,angles,prop='none'])=>({id,name,angles,prop}));
export function starter(id,current=neutral()){const def=starters.find(p=>p.id===id);if(!def)throw Error('Unknown starter pose');const s=neutral();s.hair=validateHair(current.hair);s.profile=structuredClone(current.profile);s.camera=structuredClone(current.camera);s.placement=structuredClone(current.placement);for(const [id,angles]of Object.entries(def.angles))s.rotations[id]=euler(...angles);s.prop.kind=def.prop;return validateState(s);}
